import React, { useState } from 'react';

type ButtonProps = {
  label: string;
  onPress?: (id: number) => void;
};

interface ListProps<T> {
  items: T[];
  render: (item: T) => React.ReactNode;
}

const identity = <T,>(value: T): T => value;

export function Button({ label, onPress }: ButtonProps): JSX.Element {
  const [count, setCount] = useState<number>(0);
  return (
    <button type="button" onClick={() => { setCount(count + 1); onPress?.(count); }}>
      {label}: {count}
    </button>
  );
}

export function List<T extends { id: number }>({ items, render }: ListProps<T>) {
  if (items.length === 0) {
    return <p className="empty">No items</p>;
  }
  return (
    <ul>
      {items.map((item) => (
        <li key={item.id}>{render(identity(item))}</li>
      ))}
    </ul>
  );
}

export const App = () => (
  <>
    <Button label="Add" />
    <List<{ id: number }> items={[{ id: 1 }]} render={(i) => <span>{i.id}</span>} />
  </>
);

